# Generated by Selenium IDE / Automated Test Suite
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class TestAddProduct:
    def setup_method(self, method):
        self.driver = webdriver.Chrome()
        self.driver.maximize_window()
        self.wait = WebDriverWait(self.driver, 10)

    def teardown_method(self, method):
        self.driver.quit()

    def test_add_product(self):
        # 1. Login as Administrator with pharmacy/inventory management role
        self.driver.get("http://localhost:3000/login")
        email_input = self.wait.until(EC.visibility_of_element_located((By.NAME, "email")))
        email_input.send_keys("admin@meditwin.local")
        pwd_input = self.wait.until(EC.visibility_of_element_located((By.NAME, "password")))
        pwd_input.send_keys("AdminPass@123")
        self.wait.until(EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))).click()
        
        # 2. Navigate to Pharmacy Products & Medicines Catalog
        self.wait.until(EC.url_contains("/dashboard/admin"))
        self.driver.get("http://localhost:3000/dashboard/admin/medicines")

        # 3. Click 'Add Product / Medicine' modal button
        add_product_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(text(), 'Add Product') or contains(text(), 'Add Medicine') or contains(@id, 'btn-add-product')]"))
        )
        add_product_btn.click()

        # 4. Fill in product specification fields
        prod_name_field = self.wait.until(EC.visibility_of_element_located((By.NAME, "productName")))
        prod_name_field.clear()
        prod_name_field.send_keys("Amoxicillin 500mg Capsule")

        generic_name_field = self.driver.find_element(By.NAME, "genericName")
        generic_name_field.clear()
        generic_name_field.send_keys("Amoxicillin Trihydrate")

        category_select = self.driver.find_element(By.NAME, "category")
        category_select.send_keys("Antibiotic")

        unit_select = self.driver.find_element(By.NAME, "unit")
        unit_select.send_keys("Capsule")

        price_field = self.driver.find_element(By.NAME, "price")
        price_field.clear()
        price_field.send_keys("15.00")

        stock_field = self.driver.find_element(By.NAME, "stockQuantity")
        stock_field.clear()
        stock_field.send_keys("250")

        desc_field = self.driver.find_element(By.NAME, "description")
        desc_field.clear()
        desc_field.send_keys("Broad-spectrum antibiotic medication for respiratory and systemic infections")

        # 5. Click Save / Submit Product button
        save_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(text(), 'Save') or contains(text(), 'Submit') or contains(text(), 'Add')]"))
        )
        save_btn.click()

        # 6. Verify success confirmation toast and presence in product catalog
        success_toast = self.wait.until(
            EC.visibility_of_element_located((By.XPATH, "//*[contains(text(), 'Product added successfully') or contains(text(), 'Medicine added successfully')]"))
        )
        assert success_toast.is_displayed(), "Product addition success toast was not displayed."

        new_item_row = self.wait.until(
            EC.visibility_of_element_located((By.XPATH, "//*[contains(text(), 'Amoxicillin 500mg Capsule')]"))
        )
        assert new_item_row.is_displayed(), "Newly added product does not appear in product inventory table."
